Find-Acyclic-Solution (Σ, s0, Sg)
π ← Ø
Frontier ← {s0}
for every s ∈ Frontier \ Sg do
    Frontier ← Frontier \ {s}
    if Applicable(s) = Ø then return failure
    nondeterministically choose a ∈ Applicable(s)
    π ← π ∪ (s, a)
    Frontier ← Frontier ∪ (γ(s, a) \ Domain(π))
    if has-loops(π, a, Frontier) then return failure
    return π
    frontier = {at_harbor}
    π = {(on_ship, unload)}

Find-Acyclic-Solution (Σ, s₀, S_g)
π ← Ø
Frontier ← {s₀}
for every s ∈ Frontier \ S_g do
    Frontier ← Frontier \ {s}
    if Applicable(s) = Ø then return failure
    nondeterministically choose a ∈ Applicable(s)
    π ← π ∪ (s, a)
    Frontier ← Frontier ∪ (γ(s, a) \ Domain(π))
    if has-loops(π, a, Frontier) then return failure
    return π
    frontier = {parking1, parking2, transit1}
    π = {(on_ship, unload), (at_harbor, park)}

Guided-Find-Safe-Solution (Σ,s0, Sg)
    if s0 ∈ Sg then return(∅)
    if Applicable(s0) = ∅ then return(failure)
    π ← ∅
    loop
        Q ← leaves(s0, π) \ Sg
        if Q = ∅ then do
            π ← π \ {(s, a) ∈ π | s∉ γ̂(s0, π)}
            return(π)
        select arbitrarily s ∈ Q
        π' ← Find-Solution(Σ, s, Sg)
        if π' ≠ failure then do
            π ← π ∪ {(s, a) ∈ π' | s∉ Domain(π)}
        else for every s' and a such that s ∈ γ(s', a) d
            π ← π \ {(s', a)}
            make a not applicable in s'

